import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

import { runSupportAgent } from './support-agent.js';

test('loads the canonical instruction for both Responses calls', async () => {
  const requests = [];
  const responsesClient = {
    responses: {
      create: async (request) => {
        requests.push(request);
        return { id: `response-${requests.length}` };
      },
    },
  };

  await runSupportAgent(responsesClient, 'Where is order 123?');

  const canonicalInstruction = await readFile(
    new URL('../moldea/agents/customer-support/instruction.md', import.meta.url),
    'utf8',
  );

  assert.equal(requests.length, 2);
  assert.deepEqual(requests[0], {
    input: 'Where is order 123?',
    instructions: canonicalInstruction,
  });
  assert.deepEqual(requests[1], {
    input: 'The order lookup completed successfully.',
    instructions: canonicalInstruction,
    previous_response_id: 'response-1',
  });
});

